#include <stdio.h>
#include <math.h>

int main() {
    int n;

    // Nhập bậc của đa thức
    printf("Nhap bac cua da thuc (n): ");
    scanf("%d", &n);

    float a[n + 1];

    // --- Câu a: Nhập và in các hệ số ---
    printf("\n--- CAU A ---\n");
    for (int i = 0; i <= n; i++) {
        printf("Nhap he so a[%d]: ", i);
        scanf("%f", &a[i]);
    }

    printf("Cac he so vua nhap la: ");
    for (int i = 0; i <= n; i++) {
        printf("%.2f ", a[i]);
    }
    printf("\n");

    // --- Câu b: Đếm số hệ số nhỏ hơn 0 ---
    printf("\n--- CAU B ---\n");
    int count = 0;
    for (int i = 0; i <= n; i++) {
        if (a[i] < 0) {
            count++;
        }
    }
    printf("So he so nho hon 0 la: %d\n", count);

    // --- Câu c: Tính giá trị đa thức tại x0 ---
    printf("\n--- CAU C ---\n");
    float x0;
    printf("Nhap gia tri x0: ");
    scanf("%f", &x0);

    // Sử dụng thuật toán Horner để tính giá trị đa thức nhanh và chính xác
    float val = a[n];
    for (int i = n - 1; i >= 0; i--) {
        val = val * x0 + a[i];
    }
    printf("Gia tri cua da thuc P(%.2f) = %.2f\n", x0, val);

    // --- Câu d: Tính đạo hàm cấp 1 và in các hệ số sau đạo hàm ---
    printf("\n--- CAU D ---\n");
    if (n == 0) {
        printf("Dao ham cap 1 cua hang so la: 0.00\n");
    } else {
        float b[n]; // Mảng lưu các hệ số của đa thức đạo hàm (bậc n - 1)

        // Đạo hàm: (a_i * x^i)' = i * a_i * x^(i-1)
        for (int i = 1; i <= n; i++) {
            b[i - 1] = i * a[i];
        }

        printf("Cac he so cua da thuc sau khi dao ham cap 1 (tu b_0 den b_%d) la:\n", n - 1);
        for (int i = 0; i < n; i++) {
            printf("%.2f ", b[i]);
        }
        printf("\n");
    }

    return 0;
}

